// friday13.cs — Friday the 13th experiments with the proleptic Gregorian calendar

// Find the earliest Friday the 13th starting at 0001-01-01
DateOnly date = new DateOnly(1, 1, 13); // start checking the 13th of each month
DateOnly earliest = default;

for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateOnly(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
        {
            if (earliest == default)
                earliest = d;
            break; // found one this year, but keep going for the count
        }
    }
    if (earliest != default) break;
}

// Actually search properly for the very first one
earliest = default;
for (int year = 1; year <= 9999; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateOnly(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
        {
            earliest = d;
            goto found;
        }
    }
}
found:

Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd} ({earliest.DayOfWeek})");

// Count Friday the 13ths in a full 400-year cycle (the Gregorian calendar repeats every 400 years)
int count = 0;
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateOnly(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
            count++;
    }
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");

// Bonus: which day-of-week is most likely to fall on the 13th?
var dayCounts = new int[7];
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateOnly(year, month, 13);
        dayCounts[(int)d.DayOfWeek]++;
    }
}

Console.WriteLine("\n13th falls on each day of the week (400-year cycle):");
for (int i = 0; i < 7; i++)
    Console.WriteLine($"  {(DayOfWeek)i,-10}: {dayCounts[i]}");
